@router.get('/api/backups/{task_id}/status')
async def check_backup_task_status(
    task_id: str,
    redis: aioredis.Redis = Depends(get_redis),
    current_user: User = Depends(get_current_user)
):
    job_data = await redis.hgetall(f"backup_task:{task_id}")
    if not job_data or job_data.get("owner_id") != str(current_user.id):
        raise HTTPException(status_code=404, detail="Task not found")

    return {
        "task_id": task_id,
        "status": job_data.get("status"),
        "download_url": job_data.get("download_url"),
        "file_size": job_data.get("file_size")
    }
